fun steps(n: Int): Int = 3 * n + 2

fun main() {
    var linearBand = true
    var squareFloor = true
    for (n in 2..1000) {
        if (steps(n) < 3 * n || steps(n) > 4 * n) linearBand = false
        if (steps(n) < n * n / 10) squareFloor = false
    }
    println(linearBand)
    println(squareFloor)
}
